var fs = require('fs');
var path = require('path');
var fileBasedUtilities = require('./fileBasedUtilities');
var untildify = require('untildify');

// Inside a Flatpak the sandbox paths mean nothing to the host session that
// actually reads ~/.config/autostart, so the entry has to re-enter the sandbox
// through `flatpak run`. Writing to the host autostart dir at all depends on
// --filesystem=host being granted in the manifest.
function getFlatpakId() {
  if (process.env.FLATPAK_ID) return process.env.FLATPAK_ID;
  try {
    if (fs.existsSync('/.flatpak-info')) {
      var info = fs.readFileSync('/.flatpak-info', 'utf8');
      var m = /^name=(.+)$/m.exec(info);
      if (m) return m[1].trim();
    }
  } catch (e) {}
  return null;
}

function removeStaleElectronDesktop() {
  try {
    var stale = untildify('~/.config/autostart/electron.desktop');
    if (fs.existsSync(stale)) fs.unlinkSync(stale);
  } catch (e) {}
}

module.exports = {

  /* Public */
  enable: function(arg) {
    removeStaleElectronDesktop();
    var autostartPath = this.getFilePath('eagle');

    // Handle Flatpak before the copy loop below: copying a host eagle.desktop
    // would autostart some other Eagle install, and the in-sandbox desktop file
    // carries "Exec=eagle", which does not resolve outside the sandbox.
    var flatpakId = getFlatpakId();
    if (flatpakId) {
      var fpHidden = arg && arg.isHiddenOnLaunch ? ' --hidden' : '';
      var fpData = "[Desktop Entry]\nType=Application\nVersion=1.0\nName=Eagle\nComment=Digital asset manager\nExec=flatpak run " + flatpakId + fpHidden + "\nIcon=" + flatpakId + "\nStartupNotify=false\nTerminal=false\nStartupWMClass=Eagle\n";
      return fileBasedUtilities.createFile({
        data: fpData,
        directory: this.getDirectory(),
        filePath: autostartPath
      });
    }

    var possibleDesktopFiles = [
      path.resolve(__dirname, '../../../../eagle.desktop'),
      '/run/current-system/sw/share/applications/eagle.desktop',
      '/usr/share/applications/eagle.desktop',
      untildify('~/.local/share/applications/eagle.desktop')
    ];
    for (var i = 0; i < possibleDesktopFiles.length; i++) {
      var src = possibleDesktopFiles[i];
      if (fs.existsSync(src)) {
        try {
          fs.mkdirSync(this.getDirectory(), { recursive: true });
          fs.copyFileSync(src, autostartPath);
          return Promise.resolve();
        } catch (e) {}
      }
    }
    var isHiddenOnLaunch = arg && arg.isHiddenOnLaunch;
    var hiddenArg = isHiddenOnLaunch ? ' --hidden' : '';
    var data = "[Desktop Entry]\nType=Application\nVersion=1.0\nName=Eagle\nComment=Digital asset manager\nExec=eagle" + hiddenArg + " %u\nIcon=eagle\nStartupNotify=false\nTerminal=false\nStartupWMClass=Eagle\n";
    return fileBasedUtilities.createFile({
      data: data,
      directory: this.getDirectory(),
      filePath: autostartPath
    });
  },
  disable: function(appName) {
    // getFilePath() ignores its argument and always returns eagle.desktop, so
    // calling removeFile twice raced two unlinks against the same path and the
    // loser rejected with ENOENT. The legacy electron.desktop is already dealt
    // with by removeStaleElectronDesktop().
    removeStaleElectronDesktop();
    return fileBasedUtilities.removeFile(this.getFilePath('eagle'));
  },
  isEnabled: function(appName) {
    removeStaleElectronDesktop();
    return fileBasedUtilities.isEnabled(this.getFilePath('eagle'));
  },

  /* Private */
  getDirectory: function() {
    return untildify('~/.config/autostart/');
  },
  getFilePath: function(appName) {
    return "" + (this.getDirectory()) + "eagle.desktop";
  }
};
